def find_maximal_job(task_l, d_l, lambda_l, all_jobs_of_l):
    max_response_time = -1
    maximal_job = None
    for job_j in all_jobs_of_l:
        current_response_time = calculate_response_time(job_j)
        if current_response_time > max_response_time:
            max_response_time = current_response_time
            maximal_job = job_j
        if current_response_time > (d_l + lambda_l):
            # This is the first job to exceed the threshold
            return job_j # This job is the maximal job by definition
    return maximal_job # If no job exceeds, return the one with max response time

class Job:
    def __init__(self, task_id, job_id, release_time, prev_job_completion_time=0):
        self.task_id = task_id
        self.job_id = job_id
        self.release_time = release_time
        self.completion_time = None
        self.eligible_time = max(release_time, prev_job_completion_time)

    def set_completion_time(self, time):
        self.completion_time = time

def is_task_active(task, time_t, current_jobs):
    for job in current_jobs:
        if job.task_id == task.id and job.release_time <= time_t and job.completion_time is None:
            return True
    return False

def find_t_o_gfp(t_e, m_processors, task_l, schedule_history):
    current_time = t_e
    while current_time > 0:
        # Check if all processors are busy with higher/equal priority tasks at current_time - 1
        if not are_all_processors_busy_with_hp_tasks(current_time - 1, m_processors, task_l, schedule_history):
            return current_time # t_o is the first time an idle slot or lower priority task was found
        current_time -= 1
    return 0 # If no idle slot found, t_o is 0

def has_carry_in_job(task_i, t_o, schedule_history):
    # Assuming schedule_history tracks job releases and completions
    for job in task_i.jobs_released_before(t_o):
        if job.completion_time is None or job.completion_time > t_o:
            return True
    return False

def omega_c(tau_i, L):
    if L <= 0: return 0
    # Calculate the effective interval length 'sigma'
    sigma = L - tau_i.e + tau_i.d + tau_i.lambda_val
    # Use the delta_func for carry-in workload calculation
    return delta_func(tau_i, sigma)

def I_nc_l(tau_i, tau_l, L, s_l_j):
    available_time = L - tau_l.e - s_l_j + 1
    if tau_i.id != tau_l.id:
        return min(omega_nc(tau_i, L), available_time)
    else: # i == l
        return min(omega_nc(tau_l, L) - tau_l.e, available_time)

def I_c_l(tau_i, tau_l, L, s_l_j):
    available_time = L - tau_l.e - s_l_j + 1
    if tau_i.id != tau_l.id:
        return min(omega_c(tau_i, L), available_time)
    else: # i == l
        return min(omega_c(tau_l, L) - tau_l.e, available_time)

def is_gfp_schedulable(task_set, m_processors):
    for tau_i in task_set.tasks:
        R_i_bound = gfp_response_time_bound(tau_i, task_set, m_processors)
        kappa_i = max(0, tau_i.d + tau_i.lambda_val - tau_i.p)
        # The condition in the paper is psi_max_i <= d_i + lambda_i - kappa_i
        # Since R_i_bound = psi_max_i + kappa_i, this simplifies to R_i_bound - kappa_i <= d_i + lambda_i - kappa_i
        # Which is R_i_bound <= d_i + lambda_i
        if R_i_bound > (tau_i.d + tau_i.lambda_val):
            return False # Task i misses its deadline/tardiness threshold
    return True # All tasks are schedulable

def find_t_o_gedf(t_e, m_processors, schedule_history):
    current_time = t_e
    while current_time > 0:
        # Check if any processor is idle at current_time - 1
        if is_any_processor_idle(current_time - 1, m_processors, schedule_history):
            return current_time # t_o is the first time an idle slot was found
        current_time -= 1
    return 0 # If no idle slot found, t_o is 0

def check_gedf_miss_condition(total_work_W, m_processors, xi_l, e_l, s_l_j):
    required_processor_time_for_others = m_processors * (xi_l - e_l - s_l_j)
    return total_work_W > required_processor_time_for_others

def get_te_minus_to_bound_gedf(xi_l, lambda_l, d_l, p_l):
    bound_1 = xi_l - lambda_l - d_l
    bound_2 = xi_l - p_l
    return max(bound_1, bound_2)

import math

def DBF(tau_i, t):
    if t <= 0: return 0
    # Number of jobs whose deadlines are within t, including the one ending at t
    num_jobs = math.floor(max(0, t - tau_i.d) / tau_i.p) + 1
    return max(0, num_jobs * tau_i.e)

def W_nc_gedf(tau_i, tau_l, xi_l, s_l_j):
    t_eff_dbf = xi_l - tau_l.lambda_val
    available_time = xi_l - tau_l.e - s_l_j + 1

    if tau_i.id != tau_l.id:
        return min(DBF(tau_i, t_eff_dbf), available_time)
    else: # i == l
        bound_te_to = get_te_minus_to_bound_gedf(xi_l, tau_l.lambda_val, tau_l.d, tau_l.p)
        return min(DBF(tau_l, t_eff_dbf) - tau_l.e, bound_te_to)

def W_c_gedf(tau_i, tau_l, xi_l, s_l_j):
    available_time = xi_l - tau_l.e - s_l_j + 1

    if tau_i.id != tau_l.id:
        pi_eff = xi_l - tau_l.lambda_val + tau_i.lambda_val
        return min(delta_func(tau_i, pi_eff), available_time)
    else: # i == l
        pi_eff = xi_l # For tau_l, the effective interval for delta_func is xi_l
        bound_te_to = get_te_minus_to_bound_gedf(xi_l, tau_l.lambda_val, tau_l.d, tau_l.p)
        return min(delta_func(tau_l, pi_eff) - tau_l.e, bound_te_to)

def is_gedf_schedulable(task_set, m_processors):
    for tau_l in task_set.tasks:
        lower_xi_l, upper_xi_l = get_xi_l_search_range(tau_l, task_set, m_processors, tau_l.s) # Use tau_l.s for s_l_j in phi

        for xi_l_val in range(math.ceil(lower_xi_l), math.floor(upper_xi_l) + 1):
            for s_l_j_val in range(tau_l.s + 1):
                total_work_lhs = calculate_total_gedf_work_bound(tau_l, task_set, m_processors, xi_l_val, s_l_j_val)
                available_capacity_rhs = m_processors * (xi_l_val - tau_l.e - s_l_j_val)

                if total_work_lhs > available_capacity_rhs:
                    return False # Condition 18 is met, task l is not schedulable
    return True # All tasks are schedulable
